local SaddleMaker = {}
local PRODUCTS = {
    iron_saddle = { name = "Železno sedlo", ironCost = 2, woodCost = 2, leatherCost = 3, time = 6, cost = 220, prestige = 3, happiness = 2, description = "Železno sedlo za osnovne konjenike." },
    bronze_saddle = { name = "Bronast sedlo", bronzeCost = 2, ironCost = 1, woodCost = 2, leatherCost = 3, time = 8, cost = 540, prestige = 5, happiness = 3, description = "Bronast sedlo za vdolbeno opremo." },
    silver_saddle = { name = "Srebrno sedlo", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 3, time = 12, cost = 1300, prestige = 10, happiness = 4, description = "Srebrno sedlo za plemiške konjenike." },
    gilded_saddle = { name = "Pozlačeno sedlo", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 3, time = 16, cost = 2800, prestige = 20, happiness = 5, description = "Pozlačeno sedlo za dvorne viteze." },
    jewel_set_saddle = { name = "Draguljasto sedlo", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 3, time = 20, cost = 5800, prestige = 36, happiness = 7, description = "Draguljasto sedlo za kraljevo konjenico." },
    royal_sovereign_saddle = { name = "Kraljevski suvereno sedlo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 4, time = 27, cost = 12000, prestige = 70, happiness = 13, description = "Suvereno sedlo z biseri za krono." },
}
local BUILDINGS = {
    saddle_workshop = { name = "Sedlarska delavnica", cost = { gold = 380, wood = 180, stone = 140, iron = 8 }, upkeep = 7, qualityBonus = 5 },
    saddle_house = { name = "Sedlarska hiša", cost = { gold = 1300, wood = 360, stone = 280, silver = 8, iron = 8 }, upkeep = 28, qualityBonus = 18 },
    master_saddle_atelier = { name = "Mojstrski sedlarski atelje", cost = { gold = 3200, wood = 420, stone = 540, silver = 38, gold = 8 }, upkeep = 75, qualityBonus = 30 },
    sovereign_equestrian_palace = { name = "Suverena konjeniška palača", cost = { gold = 14000, wood = 700, stone = 900, gold = 90, jewel = 20 }, upkeep = 260, qualityBonus = 55, prestigeBonus = 50 },
}
SaddleMaker.ironStock = 12; SaddleMaker.bronzeStock = 10; SaddleMaker.woodStock = 14; SaddleMaker.leatherStock = 14; SaddleMaker.silverStock = 8; SaddleMaker.goldStock = 6; SaddleMaker.jewelStock = 4; SaddleMaker.pearlStock = 4
SaddleMaker.productStock = {}; SaddleMaker.buildings = {}; SaddleMaker.maker = nil; SaddleMaker.activeMaking = {}; SaddleMaker.totalProducts = 0; SaddleMaker.dayTimer = 0
function SaddleMaker.init() SaddleMaker.ironStock=12; SaddleMaker.bronzeStock=10; SaddleMaker.woodStock=14; SaddleMaker.leatherStock=14; SaddleMaker.silverStock=8; SaddleMaker.goldStock=6; SaddleMaker.jewelStock=4; SaddleMaker.pearlStock=4; SaddleMaker.productStock={}; SaddleMaker.buildings={}; SaddleMaker.maker=nil; SaddleMaker.activeMaking={}; SaddleMaker.totalProducts=0; SaddleMaker.dayTimer=0; print("[SaddleMaker] Royal Saddle Maker System initialized (6 products, 4 buildings)") end
function SaddleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SaddleMaker.maker={name=n or ("Sedlar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sedlar najet: %s (spretnost: %d)",SaddleMaker.maker.name,s),"success") end; return true end
function SaddleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SaddleMaker.build(id) local ok,e=SaddleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SaddleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SaddleMaker.getQualityBonus() local b=0; for _,bd in ipairs(SaddleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SaddleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SaddleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SaddleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SaddleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SaddleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SaddleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SaddleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SaddleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SaddleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SaddleMaker.buildings==0 then return false,"Potrebna sedlarska delavnica" end; if not SaddleMaker.maker then return false,"Potreben sedlar" end; return true end
function SaddleMaker.make(pt,qty) qty=qty or 1; local ok,e=SaddleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SaddleMaker.ironStock=SaddleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SaddleMaker.bronzeStock=SaddleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SaddleMaker.woodStock=SaddleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SaddleMaker.leatherStock=SaddleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SaddleMaker.silverStock=SaddleMaker.silverStock-d.silverCost*qty end; if d.goldCost then SaddleMaker.goldStock=SaddleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SaddleMaker.jewelStock=SaddleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SaddleMaker.pearlStock=SaddleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SaddleMaker.maker then t=math.max(1,t-math.floor(SaddleMaker.maker.skill/13)) end; table.insert(SaddleMaker.activeMaking,{id="saddle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SaddleMaker.completeMaking(m) local q=1.0+(SaddleMaker.getQualityBonus()/100); if SaddleMaker.maker then q=q+(SaddleMaker.maker.skill/140) end; q=math.min(2.5,q); SaddleMaker.productStock[m.productType]=(SaddleMaker.productStock[m.productType] or 0)+m.quantity; SaddleMaker.totalProducts=SaddleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SaddleMaker.maker then SaddleMaker.maker.itemsMade=SaddleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SaddleMaker.maker.skill=math.min(100,SaddleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sedlo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"saddle.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SaddleMaker.update(dt) if not _G.state then return end; SaddleMaker.dayTimer=SaddleMaker.dayTimer+dt; if SaddleMaker.dayTimer>=30 then SaddleMaker.dayTimer=0; for i=#SaddleMaker.activeMaking,1,-1 do local m=SaddleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SaddleMaker.completeMaking(m); table.remove(SaddleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SaddleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SaddleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SaddleMaker.getStats() return {ironStock=SaddleMaker.ironStock,bronzeStock=SaddleMaker.bronzeStock,woodStock=SaddleMaker.woodStock,leatherStock=SaddleMaker.leatherStock,silverStock=SaddleMaker.silverStock,goldStock=SaddleMaker.goldStock,jewelStock=SaddleMaker.jewelStock,pearlStock=SaddleMaker.pearlStock,productStock=SaddleMaker.productStock,numBuildings=#SaddleMaker.buildings,hasMaker=SaddleMaker.maker~=nil,makerName=SaddleMaker.maker and SaddleMaker.maker.name or "—",makerSkill=SaddleMaker.maker and SaddleMaker.maker.skill or 0,activeMaking=#SaddleMaker.activeMaking,totalProducts=SaddleMaker.totalProducts} end
return SaddleMaker
